//java.lang.Thread.sleep(500); //Simulate latency

tw.local.multiDataSeries = [];

for(var j = 0; j < 5; j++)
{
    var dataSeries = {};

    dataSeries.seriesName = "Sample " + j;
    dataSeries.dataPoints = [];

    var i = 0;

    dataSeries.dataPoints[i] = {};
