    dataSeries.dataPoints[i].label = "Category " + i;
    i++;
    dataSeries.dataPoints[i] = {};
    dataSeries.dataPoints[i].value = Math.floor(100 * Math.random()) + j;
    dataSeries.dataPoints[i].label = "Category " + i;
    i++;

    tw.local.multiDataSeries[tw.local.multiDataSeries.length] = dataSeries;
}
